{"command": "cat > main.go <<'GOEOF'
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/url"
	"os"
	"os/exec"
	"regexp"
	"sort"
	"strings"
)

func isTTY(f *os.File) bool {
	fi, err := f.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func shellQuote(arg string) string {
	if strings.Contains(arg, " ") {
		// escape \ and "
		// observed: escape \ as \\ and " as \" ; ' and others raw
		// Actually need to escape \ and " only?
		// For header with space and \ : X:a\b c -> "X:a\\b c" (escape \)
		// For header with space and " : X:a"b c -> "X:a\"b c" (escape ")
		// For ' : raw
		r := strings.ReplaceAll(arg, "\\", "\\\\")
		r = strings.ReplaceAll(r, "\"", "\\\"")
		return "\"" + r + "\""
	}
	return arg
}

func buildCurlTable() (map[byte]bool, map[string]bool) {
	shortTakes := make(map[byte]bool)
	longTakes := make(map[string]bool)
	out, err := exec.Command("curl", "--help", "all").Output()
	if err != nil {
		return shortTakes, longTakes
	}
	lines := strings.Split(string(out), "\n")
	reLong := regexp.MustCompile(`(--[A-Za-z0-9\-\.]+)`)
	for _, line := range lines {
		if !strings.Contains(line, "--") {
			continue
		}
		m := reLong.FindStringSubmatch(line)
		if m == nil {
			continue
		}
		longFull := m[1] // with --
		longName := longFull[2:]
		idx := strings.Index(line, longFull) + len(longFull)
		rest := ""
		if idx < len(line) {
			rest = strings.TrimLeft(line[idx:], " \t")
		}
		takes := false
		if strings.HasPrefix(rest, "<") || strings.HasPrefix(rest, "[") {
			takes = true
		}
		longTakes[longName] = takes
		// short? check if line starts with short
		// match ^\s*-(X) where X != -
		trimmed := strings.TrimLeft(line, " \t")
		if len(trimmed) >= 2 && trimmed[0] == '-' && trimmed[1] != '-' {
			ch := trimmed[1]
			// short takes same as long for lines with both? For lines with only short? same logic
			// For lines with both, use long's takes
			shortTakes[ch] = takes
		}
	}
	return shortTakes, longTakes
}

func main() {
	argv0 := os.Args[0]
	args := os.Args[1:]

	shortTakes, longTakes := buildCurlTable()
	// overrides: -F and --form as booleans (mode) for separate, -i filtered
	// For table, -F currently takes=true, --form takes=true, but we treat exact as mode (boolean)
	// So keep table as is for attached handling, but handle exact separately.

	var curlArgs []string // forwarded, in order, already split/normalized? For preview, need to show split form? e.g., -uuser:pass -> -u user:pass (split). For combined -vs -> -v -s (split). Good. So curlArgs will be expanded.
	var method string = ""
	var methodRaw string = ""
	var urlStr string = "" // original as passed
	var items []string // raw items after URL (in order)
	var prettyFlag bool = false
	var curlFlag bool = false
	var formFlag bool = false // --form / -F exact mode

	// Known methods (case-insensitive, uppercased)
	knownMethods := map[string]bool{
		"GET": true, "POST": true, "PUT": true, "DELETE": true, "PATCH": true, "HEAD": true, "OPTIONS": true, "TRACE": true,
	}

	// First pass: separate curl opts vs method/url/items
	// Need to handle --, -F, --form, --pretty, --curl, -i, etc.
	// We iterate args with index.
	i := 0
	// state: haveMethodOrUrl? Actually need to track if we have seen method/url.
	// Logic: iterate, if arg == "--" then skip it (consume, not forwarded) and continue (next args are method/url/items, but -- itself not forwarded)
	// Else if arg == "--curl" exact -> curlFlag=true, consume (not forwarded)
	// Else if arg == "--pretty" exact -> prettyFlag=true, consume
	// Else if arg == "--form" exact -> formFlag=true, consume
	// Else if arg == "-F" exact -> formFlag=true, consume (not forwarded)
	// Else if arg == "-i" exact -> consume and drop (filtered, not forwarded, no effect)
