func formatHeaders(data []byte) string {
	var out strings.Builder
	lines := strings.Split(string(data), "\n")
	for _, line := range lines {
		if strings.HasPrefix(line, "< ") {
			content := line[2:]
			if strings.HasPrefix(content, "HTTP/") {
				slash := strings.Index(content, "/")
				if slash >= 0 {
					out.WriteString("\x1b[34mHTTP")
					out.WriteString("\x1b[37m/")
					rest := content[slash+1:]
					parts := strings.SplitN(rest, " ", 3)
					if len(parts) >= 2 {
						out.WriteString("\x1b[36m")
						out.WriteString(parts[0])
						out.WriteString(" ")
						out.WriteString(parts[1])
						if len(parts) == 3 {
							out.WriteString("\x1b[33m ")
							out.WriteString(parts[2])
						}
					} else {
						out.WriteString("\x1b[36m")
						out.WriteString(rest)
					}
					out.WriteString("\n\x1b[0m\n")
				} else {
					out.WriteString("\x1b[37m")
					out.WriteString(content)
					out.WriteString("\n\x1b[0m\n")
				}
			} else if content == "" {
				out.WriteString("\n")
			} else {
				idx := strings.Index(content, ":")
				if idx >= 0 {
					name := content[:idx+1]
					value := content[idx+1:]
					out.WriteString("\x1b[37m")
					out.WriteString(name)
					out.WriteString("\x1b[36m")
					out.WriteString(value)
					out.WriteString("\n\x1b[0m\n")
				} else {
					out.WriteString("\x1b[37m")
					out.WriteString(content)
					out.WriteString("\n\x1b[0m\n")
				}
			}
		} else if strings.HasPrefix(line, "curl: ") {
			out.WriteString("\x1b[31m")
			out.WriteString(line)
			out.WriteString("\x1b[0m\n")
		} else {
			continue
		}
	}
	return out.String()
}
